const CACHE='temu-offline-v25';const ASSETS=['./','index.html','style.css?v=20261007-album','app.js?v=20261007-album','invitations.js?v=20261007-album','guest-admin.js?v=20261002-v2','sync-model.js?v=20260930-5','storage.js?v=20260930-7','sync.js?v=20260930-5','vendor/qrcode.js','vendor/jsQR.js','manifest.json','icon.svg','album-admin.js?v=20261007-1'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('temu-offline-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(new URL(e.request.url).pathname.startsWith('/api/')||new URL(e.request.url).pathname.startsWith('/invite')||new URL(e.request.url).pathname.startsWith('/invitation2'))return;if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith(fetch(e.request).then(response=>{if(response.ok&&ASSETS.some(a=>new URL(a,self.registration.scope).href===e.request.url)){const copy=response.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)));}return response;}).catch(()=>caches.match(e.request).then(hit=>hit||Response.error())));});
self.addEventListener('message',e=>{if(e.data==='CHECK_CACHE')e.waitUntil(caches.open(CACHE).then(async c=>{const ready=(await Promise.all(ASSETS.map(a=>c.match(a)))).every(Boolean);e.ports[0]?.postMessage({ready});}));});
